import {uniqueHomeArticles,homeNovelties} from './observatorio-home-visits.mjs';
export function initHome({esc,date,getArticles,openNews,db}){
 const feed=document.querySelector('#feed'),essentials=document.querySelector('#news-essentials'),layout=feed.querySelector('.feed-layout'),sidebar=feed.querySelector('.feed-about'),edition=feed.querySelector('.personal-editions');
 const top=document.createElement('div');top.className='home-top-grid';edition.before(top);top.append(edition);
 const pulse=sidebar.querySelector('.economy-sidebar');top.append(pulse);
 const strip=document.createElement('section');strip.className='home-since';strip.setAttribute('aria-label','Novedades desde tu última visita');top.after(strip);
 const discover=document.createElement('section');discover.className='home-discover';essentials.after(discover);
 const photoCache=new Map();let uid=null,epoch=0,lastVisit=null,checkpoint=null,syncing=false,syncError=false;
 function visit(user){epoch++;uid=user?.id||null;lastVisit=null;checkpoint=null;syncing=false;syncError=false;if(!uid){try{lastVisit=localStorage.getItem('atlas-home-visit:guest');localStorage.setItem('atlas-home-visit:guest',new Date().toISOString());}catch{}}update();}
 db?.auth.getSession().then(({data})=>visit(data.session?.user));db?.auth.onAuthStateChange((e,s)=>{if((s?.user?.id||null)!==uid)visit(s?.user);});
 async function syncVisit(rows){if(!uid||checkpoint||syncing||syncError||feed.hidden||!rows.length)return;syncing=true;const token=epoch;try{const {data,error}=await db.rpc('atlas_dev_home_visit',{p_ids:rows.slice(0,300).map(a=>a.id)});if(token!==epoch)return;if(error||!data?.current)throw Error();checkpoint=data;lastVisit=data.previous;}catch{if(token===epoch)syncError=true;}finally{if(token===epoch){syncing=false;update();}}}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)update();});
 new MutationObserver(()=>{if(!feed.hidden)update();}).observe(feed,{attributes:true,attributeFilter:['hidden']});
 async function photo(a,host){if(!a||!host||host.querySelector('img'))return;const token=epoch;const q=a.searchQuery?'&q='+encodeURIComponent(a.searchQuery):'';try{let info=photoCache.get(a.id);if(info===undefined){const r=await fetch('/.netlify/functions/news-image?id='+encodeURIComponent(a.id)+q);info=r.ok?(await r.json()).image:null;photoCache.set(a.id,info);}if(!info||token!==epoch||!host.isConnected)return;const image=document.createElement('img');image.alt=info.alt||'Imagen de '+info.source;image.loading='lazy';image.onerror=()=>{host.replaceChildren();host.hidden=true;};image.onload=()=>{if(image.naturalWidth<160){image.remove();return;}host.hidden=false;};const credit=document.createElement('a');credit.textContent='Imagen: '+info.source+' ↗';const url=new URL(info.articleUrl);if(url.protocol!=='https:')return;credit.href=url.href;credit.target='_blank';credit.rel='noopener noreferrer';host.append(image,credit);image.src='/.netlify/functions/news-photo?id='+encodeURIComponent(a.id)+q;}catch{}}
 function update(){const rows=uniqueHomeArticles(getArticles().filter(a=>a.reading?.status==='ready'));syncVisit(rows);const since=Date.parse(lastVisit),newRows=uid?homeNovelties(rows,checkpoint||{}):Number.isFinite(since)?rows.filter(a=>Date.parse(a.publishedAt)>since):[];strip.innerHTML='<strong>Desde tu última visita</strong><span>'+ (uid&&!checkpoint?(syncError?'No se pudo sincronizar tu última visita.':'Sincronizando tu última visita…'):Number.isFinite(since)?newRows.length+' noticias publicadas desde '+esc(date(lastVisit)):'Tu primer panorama: explora las noticias disponibles')+'</span><button>Ver noticias →</button>';strip.querySelector('button').onclick=()=>{feed.querySelector('#news-feed').scrollIntoView({behavior:'smooth',block:'start'});};
 if(newRows.length){const list=document.createElement('details');list.className='home-new-list';list.innerHTML='<summary>Ver '+newRows.length+' novedades sin repetir</summary>'+newRows.map((a,i)=>'<p><button data-new-story="'+i+'">'+esc(a.title)+'</button> <small>'+esc(a.source)+' · '+esc(date(a.publishedAt))+'</small></p>').join('');strip.append(list);list.querySelectorAll('[data-new-story]').forEach(b=>b.onclick=()=>openNews(newRows[Number(b.dataset.newStory)]));strip.querySelector('button').onclick=()=>{list.open=true;};}
 // Choose a different topic from the leading story. This is discovery, not an inferred user interest.
 const lead=rows[0],other=rows.find(a=>a.id!==lead?.id&&a.topics?.[0]!==lead?.topics?.[0]);discover.hidden=!other;if(other){discover.innerHTML='<span class="eyebrow">AMPLÍA TU MIRADA</span><div class="home-discover-body"><figure hidden></figure><div><h2>'+esc(other.title)+'</h2><p>'+esc(other.reading.what?.[0]?.text||'')+'</p><p class="muted">'+esc(other.source)+' · '+esc(date(other.publishedAt))+'</p><button>Leer esta historia →</button></div></div>';discover.querySelector('button').onclick=()=>openNews(other);photo(other,discover.querySelector('figure'));}
 essentials.querySelectorAll('.essential-card').forEach(card=>{const b=card.querySelector('[data-essential]');const a=rows.find(a=>a.id===b?.dataset.essential)||rows.find(a=>a.coverage?.members?.some(m=>m.id===b?.dataset.essential));if(!a||card.querySelector('.home-essential-photo'))return;const figure=document.createElement('figure');figure.className='home-essential-photo';figure.hidden=true;card.prepend(figure);photo(a,figure);});
 }
 const observer=new MutationObserver(()=>updatePhotos());observer.observe(essentials,{childList:true});function updatePhotos(){const rows=getArticles();essentials.querySelectorAll('.essential-card').forEach(card=>{if(card.querySelector('.home-essential-photo'))return;const id=card.querySelector('[data-essential]')?.dataset.essential,a=rows.find(a=>a.id===id);if(!a)return;const f=document.createElement('figure');f.className='home-essential-photo';f.hidden=true;card.prepend(f);photo(a,f);});}
 return {update};
}
